appB_content.append('## B.1 Jira Query Language (JQL) Master Reference\n')
appB_content.append('JQL is a flexible SQL-like syntax used to query issues across Jira Data Center and Jira Cloud. Standard clause structure follow: `[Field] [Operator] [Value/Function] [ORDER BY Field ASC|DESC]`.\n')

appB_content.append('### JQL Operators Reference')
appB_content.append('| Operator | Description | Example Syntax |')
appB_content.append('| --- | --- | --- |')
appB_content.append('| `=` | Exact equality match | `project = "PAYMENTS"` |')
appB_content.append('| `!=` | Inequality match | `status != "Closed"` |')
appB_content.append('| `>` / `>=` | Greater than (dates/numbers) | `created >= "-7d"` |')
appB_content.append('| `<` / `<=` | Less than (dates/numbers) | `storyPoints <= 5` |')
appB_content.append('| `IN` | Matches any value in set | `status IN ("In Progress", "In Review")` |')
appB_content.append('| `NOT IN` | Excludes all values in set | `priority NOT IN ("Low", "Trivial")` |')
appB_content.append('| `~` | Fuzzy text search (contains) | `summary ~ "authentication failure"` |')
appB_content.append('| `!~` | Fuzzy text exclusion | `description !~ "deprecated"` |')
appB_content.append('| `IS EMPTY` | Field contains null/no value | `"Epic Link" IS EMPTY` |')
appB_content.append('| `IS NOT EMPTY` | Field contains valid value | `"Sprint" IS NOT EMPTY` |')
appB_content.append('| `WAS` | Historical status match | `status WAS "In Progress"` |')
appB_content.append('| `WAS IN` | Historical status set match | `status WAS IN ("Blocked", "Testing")` |')
appB_content.append('| `CHANGED` | Status/field change event | `status CHANGED DURING ("2026-01-01", "2026-03-31")` |')

