appB_content.append('| --- | --- | --- |')
appB_content.append('| `currentUser()` | User ID | Evaluates to logged-in user: `assignee = currentUser()` |')
appB_content.append('| `membersOf("group")` | Group Users | Matches members of group: `assignee IN membersOf("jira-coaches")` |')
appB_content.append('| `openSprints()` | Sprint IDs | Active open sprints: `sprint IN openSprints()` |')
appB_content.append('| `closedSprints()` | Sprint IDs | Completed sprints: `sprint IN closedSprints()` |')
appB_content.append('| `futureSprints()` | Sprint IDs | Planned future sprints: `sprint IN futureSprints()` |')
